#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    const int SKU_COUNT = 5;
    long stock[5] = {0, 0, 0, 0, 0};
    long price[5] = {10, 20, 30, 40, 50}; // assumed price list
    long revenue = 0;

    int i = 1;
    while (i + 2 < argc) {
        const char *op = argv[i];
        char *endptr;
        long sku = strtol(argv[i + 1], &endptr, 10);
        (void)endptr; // ignore errors, mimic original behavior
        long qty = strtol(argv[i + 2], &endptr, 10);
        (void)endptr;
        i += 3;

        if (strcmp(op, "S") == 0) { // sell
            if (sku < 0 || sku >= SKU_COUNT) {
                puts("INVALID_SKU");
                continue;
            }
            if (qty < 0) {
                printf("INSUFFICIENT_STOCK sku=%ld\n", sku);
                continue;
            }
            if (stock[sku] < qty) {
                printf("INSUFFICIENT_STOCK sku=%ld\n", sku);
                continue;
            }
            stock[sku] -= qty;
            long added = price[sku] * qty;
            revenue += added;
            printf("SELL sku=%ld qty=%ld revenue+=%ld\n", sku, qty, added);
        } else if (strcmp(op, "R") == 0) { // restock
            if (sku < 0 || sku >= SKU_COUNT) {
                puts("INVALID_SKU");
                continue;
            }
            if (qty < 0) {
                printf("INSUFFICIENT_STOCK sku=%ld\n", sku);
                continue;
            }
            stock[sku] += qty;
            printf("RESTOCK sku=%ld qty=%ld\n", sku, qty);
        } else {
            puts("INVALID_OP");
        }
    }

    printf("FINAL stock=");
    for (int j = 0; j < SKU_COUNT; ++j) {
        printf("%ld", stock[j]);
        if (j < SKU_COUNT - 1) {
            putchar(',');
        }
    }
    printf(" revenue=%ld\n", revenue);
    return 0;
}
